insert into public.posts(title,slug,excerpt,body,category,status,is_featured,seo_title,seo_description,focus_keyword,seo_keywords,robots_index,robots_follow,schema_type)
values
('چرا لانگ پات را از دست می‌دهیم؟','why-long-pots-miss','سه عامل مهم در خطای لانگ پات: نشانه‌گیری، حرکت چوب و کنترل سرعت.','<h2>لانگ پات فقط نشانه‌گیری نیست</h2><p>اگر مسیر حرکت چوب در لحظه ضربه از خط هدف منحرف شود، حتی نشانه‌گیری درست هم کافی نیست. قبل از ضربه، وضعیت بدن، خط چوب و نقطه تماس را بررسی کن.</p><h2>تمرین پیشنهادی</h2><p>یک موقعیت ثابت انتخاب کن، ۱۰ ضربه با سرعت کنترل‌شده بزن و نتیجه هر ضربه را ثبت کن. به‌جای تغییر هم‌زمان چند عامل، هر بار فقط یک مورد را اصلاح کن.</p>','article','draft',false,'چرا لانگ پات در اسنوکر خراب می‌شود؟','سه عامل رایج در از دست دادن لانگ پات و یک تمرین ساده برای بررسی حرکت چوب و دقت ضربه.','لانگ پات',array['آموزش اسنوکر','لانگ پات','Cue Action'],true,true,'Article'),
('بعد از یک Miss چه کار می‌کنی؟','what-to-do-after-a-miss','ضربه قبلی تمام شده؛ تصمیم بعدی هنوز دست توست.','<h2>ضربه بعدی مهم است</h2><p>بعد از یک Miss، به‌جای عجله برای جبران، دلیل احتمالی خطا را کوتاه مرور کن و سپس توجهت را به وضعیت جدید میز برگردان.</p><p>سؤال امروز: بعد از یک اشتباه، بیشتر عصبانی می‌شوی یا سریع به برنامه بازی برمی‌گردی؟</p>','story','draft',false,'مدیریت اشتباه در اسنوکر','چطور بعد از یک ضربه ناموفق تمرکزمان را برای ادامه فریم حفظ کنیم؟','تمرکز در اسنوکر',array['روانشناسی اسنوکر','تمرکز','تمرین اسنوکر'],true,true,'Article'),
('پات یا سیفتی؟ تو انتخاب کن','pot-or-safety-your-choice','وقتی پات ریسک بالایی دارد، چه زمانی Safety انتخاب بهتری است؟','<h2>قبل از انتخاب ضربه</h2><p>زاویه پات، فاصله توپ سفید تا توپ هدف، مسیر برگشت سفید و توپ‌هایی که بعد از Miss برای حریف باقی می‌مانند را بررسی کن.</p><p>این پست فعلاً پیش‌نویس است. تصویر واقعی موقعیت میز و گزینه‌های پاسخ باید پیش از انتشار اضافه شوند؛ بدون موقعیت مشخص، پاسخ قطعی وجود ندارد.</p>','article','draft',false,'پات یا سیفتی در اسنوکر','تمرینی برای بررسی انتخاب ضربه با توجه به ریسک پات و موقعیت میز.','سیفتی در اسنوکر',array['Safety','Pot','تاکتیک اسنوکر'],true,true,'Article'),
('چطور Cue Action را بررسی کنیم؟','how-to-check-cue-action','حرکت چوب باید قابل تکرار، روان و در امتداد خط ضربه باشد.','<h2>سه نکته برای بررسی</h2><p>در تمرین، خط حرکت چوب، ثبات سر و ادامه حرکت بعد از تماس را بررسی کن. یک ویدئو از زاویه مناسب بگیر تا حرکت را بهتر ببینی.</p><p>از ضربه‌های ساده شروع کن و قبل از افزایش قدرت، روی تکرارپذیری تمرکز داشته باش.</p>','article','draft',false,'بررسی Cue Action در اسنوکر','چند نکته کاربردی برای بررسی حرکت چوب و تمرین تکرارپذیری ضربه در اسنوکر.','Cue Action',array['آموزش اسنوکر','حرکت چوب','Cue Action'],true,true,'Article')
